@@ -0,0 +1,93 @@
+import * as path from 'path';
+import * as fs from 'fs';
+
+import { test as setup } from '@playwright/test';
+
+const authFile = path.join(__dirname, '../../.auth/e2e-user.json');
+
+const BASE_URL = process.env.BASE_URL || 'http://localhost:3000';
+const LOCALE = 'ja-JP';
+const TEST_USER = {
+  email: process.env.TEST_USER_EMAIL || 'e2e@gazai.io',
+  password: process.env.TEST_USER_PASSWORD || 'TEST_USER_PASSWORD'
+};
+
+setup('authenticate', async ({ page }) => {
+  console.log('🚀 E2E Auth Setup: Logging in to save authentication state...');
+  console.log(`   Target: ${BASE_URL}`);
+  console.log(`   User: ${TEST_USER.email}`);
+
+  // Navigate to home page
+  const homeUrl = `${BASE_URL}/${LOCALE}`;
+  await page.goto(homeUrl, { waitUntil: 'domcontentloaded' });
+  await page.waitForLoadState('networkidle').catch(() => {});
+
+  // Check if already logged in
+  const userProfileButton = page.getByTestId('user-profile-button');
+  const isAlreadyLoggedIn = await userProfileButton
+    .isVisible()
+    .catch(() => false);
+
+  if (isAlreadyLoggedIn) {
+    console.log('   ✅ Already logged in, saving state...');
+  } else {
+    console.log('   🔐 Not logged in, starting login flow...');
+
+    // Click login button
+    const loginButton = page.getByTestId('header-login-button');
+    await loginButton.waitFor({ state: 'visible', timeout: 10000 });
+    await loginButton.click();
+
+    // Wait for auth dialog
+    const authDialog = page.getByTestId('auth-dialog');
+    await authDialog.waitFor({ state: 'visible', timeout: 5000 });
+
+    // Click email login
+    const emailButton = page.getByTestId('auth-email-button');
+    await emailButton.click();
+
+    // Enter credentials
+    await page.fill('input[name="email"]', TEST_USER.email);
+    await page.fill('input[name="password"]', TEST_USER.password);
+
+    // Submit login
+    const submitButton = page.getByTestId('login-submit-button');
+    await submitButton.click();
+
+    // Wait for login to complete
+    await page.waitForLoadState('networkidle');
+    await userProfileButton.waitFor({ state: 'visible', timeout: 15000 });
+    console.log('   ✅ Login successful');
+
+    // Handle daily token claim dialog if it appears
+    try {
+      const claimTokensButton = page.getByTestId('claim-tokens-button');
+      const claimVisible = await claimTokensButton
+        .waitFor({ state: 'visible', timeout: 5000 })
+        .then(() => true)
+        .catch(() => false);
+
+      if (claimVisible) {
+        await claimTokensButton.click();
+        console.log(
+          '   ✅ Claimed daily tokens (will not appear in subsequent tests)'
+        );
+        await page.waitForTimeout(1000);
+      }
+    } catch {
+      // Dialog not present or already claimed
+      console.log('   ℹ️  No daily token claim dialog');
+    }
+  }
+
+  // Ensure the .auth directory exists
+  const authDir = path.dirname(authFile);
+  if (!fs.existsSync(authDir)) {
+    fs.mkdirSync(authDir, { recursive: true });
+  }
+
+  // Save authentication state
+  await page.context().storageState({ path: authFile });
+  console.log(`   ✅ Authentication state saved to: ${authFile}`);
+  console.log('🎉 Auth setup complete! All tests will reuse this session.');
+});
